package peroxicore.ponder.api.dsl

import peroxicore.ponder.scene.*

/**
 * Concrete action scope used by timelines and keyframes.
 *
 * The whole action surface lives in [WorldPonderActionScopeApi], which is generated by KSP from
 * peroxicore.ponder.api.template.WorldPonderActionScopeTemplate. This class only binds a
 * [TimelineContext] to it.
 */
@PonderDslMarker
open class WorldPonderActionScope(
  val context: TimelineContext,
) : WorldPonderActionScopeApi,
  TimelineContext by context
